You are debugging a Hermes Agent Desktop sidebar plugin written in PLAIN JS (no JSX transform; it must use jsx()/jsxs() from react/jsx-runtime).

## CONFIRMED SYMPTOM (from screenshot)
The plugin page renders, but FOUR things are wrong:
1. "Projects in rotation" shows: "Nothing yet - open the picker and tick some repos." -- while the picker on the SAME page says "3 projects selected", and the backing script really does return 3 projects. So the table renders EMPTY.
2. A RED ERROR BOX shows "unexpected output:" followed by a fragment that looks like the MIDDLE of a JSON blob, e.g.:
   unexpected output: s_rmg verbatim, ambience_chatter inline) into world.seeded.seeded_rmg; gate 180 pass/3 skip; commit 9bdf86("", "duration": "1.6s", "note": "", "kind": "code", "icon": "lu83dudc40", "text": "import re, glob, ast, collections", ...
3. "Chain of thought" says "nothing in flight / No round in flight" even though the loop IS running and the worker log is fresh (log_age_s ~45).
4. "Loop settings" and "Discovery" render CORRECT values.

## DATA PATH
The plugin calls host.requestProfile(route, "shell.exec", {command}, timeoutMs) and JSON.parses stdout.
All four commands verified from a normal shell to return PURE JSON:
  activity.py               -> {"ts":..,"running":true,"projects":[...],"rows":[...],"cot":{...}}
  discover.py report --json -> {"stats":{...}}
  loopctl.py status --json  -> {"running":..,"projects":[..],"rounds_done":..}
  checkpoint.py all         -> {...}

activity.py rows:
  {"name":"tombs-and-tyrants","never_rotated":false,"active_task":"t_42fa5ba4","active_status":"running","elapsed":"1.7h","open_cards":1,"rounds":3,"running":true}
activity.py cot:
  {"steps":[{"kind":"think","icon":"..","text":"..","duration":"","note":""},...],"task":"t_42fa5ba4","project":"tombs-and-tyrants","steps_total":238,"log_age_s":45,"log_bytes":73772,"log_path":"C:\\..."}
NOTE: there is NO "live" key in cot.

## YOUR JOB
Read the attached plugin.js (and cot-card.js = the CoT region). Find the ROOT CAUSE of ALL FOUR symptoms. Be specific: quote exact lines, explain WHY each fails.

Focus on:
- How rows/actRows is derived; whether a renamed/stale variable is read (e.g. act0 vs act0.data).
- Which hook emits "unexpected output:", and why a JSON blob would appear truncated mid-string with a partial object appended.
- Whether cot.live is ever populated.
- Any property read that does not exist on the real payload.

Then give the MINIMAL fix per defect. Do NOT rewrite the whole file.
OUTPUT FORMAT: numbered defects, each with (a) exact quoted code, (b) why it breaks, (c) minimal patch.


===== plugin.js =====
// Karpathy Loop — a Hermes desktop plugin.
//
// Adds "Karpathy Loop" to the sidebar (next to Artifacts / Scheduled / RSS)
// with a page that:
//   * shows live loop status (running|paused, projects in rotation, rounds)
//   * drives the loop from inside the app: Save rotation / Start / Pause /
//     Run discovery / Refresh
//   * embeds the project picker UI (selector.html) built by the Python side
//
// Data path: the same bridge the RSS plugin uses --
//   host.requestProfile(route, "shell.exec", { command })
// -- so we shell out to the Python tools in C:\CODING\project-improver and read
// their JSON. No new backend service is required.
//
// NOTE: disk plugins load precompiled. No raw JSX here; build elements with
// jsx()/jsxs() from react/jsx-runtime (see the hermes-rss plugin for the shape).

import React, { useCallback, useEffect, useMemo, useState } from "react";
import { Fragment, jsx, jsxs } from "react/jsx-runtime";
import {
  Button,
  host,
  useValue,
  ROUTES_AREA,
  SIDEBAR_NAV_AREA,
  PALETTE_AREA,
} from "@hermes/plugin-sdk";

var ID = "karpathy-loop";

const ROOT = "C:\\CODING\\project-improver";
const PY = "C:\\Users\\gene\\AppData\\Local\\hermes\\hermes-agent\\venv\\Scripts\\python.exe";
const SEL_HTML = ROOT + "\\selector.html";

// ---------------------------------------------------------------- bridge
// Route resolution copied from the PROVEN hermes-rss plugin, which is bundled
// and therefore known-good against this SDK build:
//   profile       must be a non-empty STRING (the SDK calls profile.trim())
//   connectionId  is a string, defaulting to "local"
//   the pair      must exist in host2.profileRoutes()
// Passing an undefined profile made the SDK throw
//   "Cannot read properties of undefined (reading 'trim')"
// inside retainProfile/requestProfile -- which surfaced as an error in every
// panel, because every panel goes through runPy().
async function currentRoute(host2) {
  const profile = host2.state.profile.get();
  const connectionId = host2.state.connectionId?.get() || "local";
  const routes = await host2.profileRoutes();
  const route =
    (routes || []).find(
      (r) => r.profile === profile && r.connectionId === connectionId
    ) || (routes || [])[0];
  if (!route) {
    throw new Error(
      "No connected Hermes profile. Open a connection first, then reopen this tab."
    );
  }
  return route;
}

function assertOwner(host2, route) {
  // The route may change while a command runs (user switched profiles);
  // refuse to apply stale output. Same guard the RSS plugin uses.
  const nowConn = host2.state.connectionId?.get?.() || "local";
  const nowProf = host2.state.profile?.get?.();
  if (route.connectionId !== nowConn || route.profile !== nowProf) {
    throw new Error("Route changed during command");
  }
}

async function runPy(host2, route, args, timeoutMs) {
  assertOwner(host2, route);
  // shell.exec takes ONLY { command } -- the proven contract used by the bundled
  // hermes-rss plugin. Passing extra fields (cwd, timeout_ms) made the call
  // return without `stdout`, and the SDK's own `result.stdout.trim()` then threw
  // "Cannot read properties of undefined (reading 'trim')" in every panel.
  //
  // The timeout is the FOURTH POSITIONAL argument of requestProfile, not a field
  // in params (see apps/desktop/src/sdk/index.ts requestProfile signature).
  //
  // cwd is folded into the command instead. Use `cd /d` so a drive change works
  // under cmd.exe, and backslash paths -- MSYS rewrites /c/... style arguments.
  const command = 'cd /d "' + ROOT.replace(/\//g, "\\") + '" && "' + PY + '" ' + args;
  const result = await host2.requestProfile(
    route, "shell.exec", { command }, timeoutMs || 300000
  );
  assertOwner(host2, route);
  if (!result) throw new Error("No result from shell.exec for: " + command);
  if (result.code !== 0) {
    throw new Error(
      "Command failed: " + command + "\n" +
      String(result.stderr || result.stdout || "").slice(0, 400)
    );
  }
  return String(result.stdout == null ? "" : result.stdout).trim();
}

// ---------------------------------------------------------------- hooks
/* LIVE ACTIVITY -- what the loop is doing RIGHT NOW.
   The other panels show configuration; this one shows motion: which project is
   mid-round, which card is in flight, and how many rounds each has had. Without
   it the widget looks frozen while work is actually happening. */
function useActivity(host2, route, tick) {
  const [state, setState] = useState({ loading: true, data: null, error: null });
  useEffect(() => {
    let alive = true;
    if (!route) return () => { alive = false; };
    (async () => {
      try {
        const out = await runPy(host2, route, "activity.py", 90000);
        if (!alive) return;
        let parsed = null;
        try { parsed = JSON.parse(out); } catch (e) { parsed = null; }
        if (!parsed) {
          setState({ loading: false, data: null, error: "unexpected output:\n" + out.slice(0, 300) });
          return;
        }
        setState({ loading: false, data: parsed, error: null });
      } catch (e) {
        if (!alive) return;
        setState({ loading: false, data: null, error: String(e.message || e) });
      }
    })();
    return () => { alive = false; };
  }, [host2, route && route.connectionId, route && route.profile, tick]);
  return state;
}

function useCheckpoints(host2, route, tick) {
  const [state, setState] = useState({ loading: true, rows: [], error: null });
  useEffect(() => {
    let alive = true;
    if (!route) return () => { alive = false; };
    (async () => {
      try {
        const out = await runPy(host2, route, "checkpoint.py all", 90000);
        if (!alive) return;
        let parsed = null;
        try { parsed = JSON.parse(out); } catch (e) { parsed = null; }
        if (!parsed) {
          setState({ loading: false, rows: [], error: "unexpected output:\n" + out.slice(0, 300) });
          return;
        }
        setState({ loading: false, rows: parsed.checkpoints || [], error: null });
      } catch (e) {
        if (!alive) return;
        setState({ loading: false, rows: [], error: String(e.message || e) });
      }
    })();
    return () => { alive = false; };
  }, [host2, route && route.connectionId, route && route.profile, tick]);
  return state;
}

function useLoopStatus(host2, route, tick) {
  const [state, setState] = useState({ loading: true, text: "", json: null, error: null });
  useEffect(() => {
    let alive = true;
    if (!route) return () => { alive = false; };
    (async () => {
      try {
        const out = await runPy(host2, route, "loopctl.py status --json", 30000);
        if (!alive) return;
        let parsed = null;
        const i = out.indexOf("{");
        if (i !== -1) { try { parsed = JSON.parse(out.slice(i)); } catch (e) { parsed = null; } }
        setState({ loading: false, text: out, json: parsed, error: null });
      } catch (e) {
        if (!alive) return;
        setState({ loading: false, text: "", json: null, error: String(e.message || e) });
      }
    })();
    return () => { alive = false; };
  }, [host2, route && route.connectionId, route && route.profile, tick]);
  return state;
}

function useDiscovery(host2, route, tick) {
  const [state, setState] = useState({ loading: true, data: null, error: null });
  useEffect(() => {
    let alive = true;
    if (!route) return () => { alive = false; };
    (async () => {
      try {
        // --json keeps stdout PURE JSON. Without it discover.py prints an
        // aligned text table first, JSON.parse fails, and the raw fragment
        // leaks into the panel as "unexpected output: ...".
        const out = await runPy(host2, route, "discover.py report --json", 60000);
        if (!alive) return;
        let parsed = null;
        try { parsed = JSON.parse(out); } catch (e) { parsed = null; }
        if (!parsed) {
          setState({ loading: false, data: null,
                     error: "discovery returned non-JSON:\n" + String(out).slice(0, 200) });
          return;
        }
        setState({ loading: false, data: parsed, error: null });
      } catch (e) {
        if (!alive) return;
        setState({ loading: false, data: null, error: String(e.message || e) });
      }
    })();
    return () => { alive = false; };
  }, [host2, route && route.connectionId, route && route.profile, tick]);
  return state;
}


// ---------------------------------------------------------------- view helpers
/** Clip long text to n chars, preferring a clean break on whitespace. */
function shorten(s, n) {
  const t = String(s == null ? "" : s).replace(/\s+/g, " ").trim();
  if (t.length <= n) return t;
  const cut = t.slice(0, n);
  const sp = cut.lastIndexOf(" ");
  return (sp > n * 0.6 ? cut.slice(0, sp) : cut) + "…";
}

/** Strip the vault/worktree prefix so paths fit the panel. */
/** "34s" / "12m" / "2.1h" -- how long ago the worker last wrote to its log. */
function ago(sec) {
  const s = Math.max(0, Number(sec) || 0);
  if (s < 60) return Math.round(s) + "s ago";
  if (s < 3600) return Math.round(s / 60) + "m ago";
  return (s / 3600).toFixed(1) + "h ago";
}

function tidyPath(s) {
  let t = String(s || "");
  // Keep the two most useful segments:
  //   "D:\\ZCODE\\TOMBS AND TYRANTS\\.worktrees\\t_42fa5ba4\\backend\\world\\event_ledger.py"
  //     -> "world/event_ledger.py"
  const m = t.match(/\\.worktrees\\[^\\]+\\(.+)$/);
  if (m) t = m[1];
  const parts = t.split(/[\\/]/).filter(Boolean);
  return parts.length > 2 ? parts.slice(-2).join("/") : parts.join("/");
}


/** key/value rows for the Discovery panel (parsed, not a JSON dump). */
function discoRows(disc) {
  const d = (disc && disc.data) || null;
  if (!d) {
    return jsx("div", { style: S.kvEmpty,
      children: disc && disc.loading ? "\u2026" : "no data" });
  }
  // discover.py report --json emits { stats: {...} }.
  const s = d.stats || d;
  const rows = [
    ["runs", s.runs],
    ["last run", s.last_run ? String(s.last_run).slice(0, 16).replace("T", " ") : "\u2014"],
    ["threads tracked", s.threads_tracked],
    ["codebases seen", s.codebases_seen],
    ["new additions", s.additions],
    ["attached to a project", s.attached],
    ["standalone (workable)", s.standalone],
  ].filter(function (kv) { return kv[1] !== undefined && kv[1] !== null; });

  return kvTable(rows, "disco");
}

/** key/value rows for the loop settings panel. */
function settingsRows(status, act0) {
  const j = (status && status.json) || {};
  const rows = [
    ["angles per visit", j.angles_per_visit],
    ["rounds done", j.rounds_done],
    ["max rounds", j.max_rounds || "unlimited"],
    ["push to GitHub", j.pushed_to_github === undefined ? null
                        : (j.pushed_to_github ? "yes" : "no")],
    ["implementer", j.implementer],
    ["reviewer", j.reviewer],
    ["sweep every", j.sweep_minutes ? (j.sweep_minutes / 60) + " h" : null],
  ].filter(function (kv) { return kv[1] !== undefined && kv[1] !== null && kv[1] !== ""; });
  if (!rows.length) {
    return jsx("div", { style: S.kvEmpty,
      children: status && status.error ? String(status.error) : "\u2026" });
  }
  return kvTable(rows, "set");
}

/** Shared two-column key/value table so every panel looks the same. */
function kvTable(rows, key) {
  return jsx("div", { style: S.tblWrap, children: jsx("table", {
    style: S.tbl, children: jsx("tbody", { children: rows.map(function (kv, i) {
      return jsxs("tr", { style: i === rows.length - 1 ? S.trLast : S.tr,
                          children: [
        jsx("td", { style: S.tdKey, children: kv[0] }),
        jsx("td", { style: S.tdVal, children: shorten(String(kv[1]), 64) }),
      ] }, key + i);
    }) }),
  }) });
}

/** The chain-of-thought feed: the agent's reasoning + every tool call. */
function cotCard(props) {
  const cot = props.cot || {};
  const steps = cot.steps || [];
  // activity.py does not emit `live`; liveness is implied by having a task and
  // a recently-written log. Treat the log as live for 10 minutes.
  const live = (cot.task && (typeof cot.log_age_s !== "number" || cot.log_age_s < 600))
    ? { project: cot.project, task: cot.task } : null;

  let body;
  if (props.error) {
    body = jsx("div", { style: S.cotErr, children: String(props.error) });
  } else if (!steps.length) {
    body = jsx("div", { style: S.empty, children: live
      ? "waiting for the first step…"
      : "No round in flight. Press Start loop — steps appear here as the agent works." });
  } else {
    body = jsx("div", { style: S.cotScroll,
      children: steps.map(function (s, i) { return cotStep(s, i); }) });
  }

  return jsxs("div", { style: S.cotCard, children: [
    jsxs("div", { style: S.cotHead, children: [
      jsx("span", { style: S.cotTitle, children: "Chain of thought" }),
      jsx("span", { style: S.cotSub, children: live
        ? live.project + " \u00b7 " + live.task
          + (cot.steps_total ? " \u00b7 " + cot.steps_total + " steps" : "")
          + (typeof cot.log_age_s === "number"
              ? " \u00b7 updated " + ago(cot.log_age_s) : "")
        : "nothing in flight" }),
      jsx("span", { style: { marginLeft: "auto" },
        children: jsx(Button, {
          onClick: props.onRefresh, disabled: !!props.busy, children: "Refresh" }) }),
    ] }),
    body,
  ] });
}

/** One step: an italic reasoning card, or a monospace tool line. */
function cotStep(s, i) {
  const isThink = s.kind === "think";
  return jsxs("div", {
    style: isThink ? S.cotThink : S.cotStep,
    key: i,
  }, [
    jsx("span", { style: S.cotIcon,
      children: isThink ? "\u{1F9E0}" : (s.icon || "·") }),
    jsxs("div", { style: S.cotBody, children: [
      jsx("div", { style: isThink ? S.cotThinkText : S.cotStepText,
        children: shorten(isThink ? s.text : tidyPath(s.text),
                          isThink ? 320 : 150) }),
      jsxs("div", { style: S.cotMeta, children: [
        isThink ? "reasoning" : s.kind,
        s.duration ? " · " + s.duration : "",
        s.note ? " · " + shorten(s.note, 80) : "",
      ] }),
    ] }),
  ]);
}

// ---------------------------------------------------------------- styles
const S = {
  wrap: { padding: "18px 22px", fontFamily: "inherit", color: "var(--foreground)" },
  hrow: { display: "flex", alignItems: "center", gap: 10, flexWrap: "wrap" },
  h2: { margin: 0, fontSize: 20, fontWeight: 650, letterSpacing: -0.2 },
  badgeOn: { fontSize: 10.5, padding: "3px 10px", borderRadius: 999,
             border: "1px solid #1c4a38", color: "#fff", background: "#2f9e44",
             fontWeight: 700, letterSpacing: 0.5, textTransform: "uppercase" },
  badgeOff: { fontSize: 10.5, padding: "3px 10px", borderRadius: 999,
              border: "1px solid #6b5217", color: "#fff", background: "#b8860b",
              fontWeight: 700, letterSpacing: 0.5, textTransform: "uppercase" },
  badgeErr: { fontSize: 10.5, padding: "3px 10px", borderRadius: 999,
              border: "1px solid #7a2c2c", color: "#fff", background: "#c0392b",
              fontWeight: 700, letterSpacing: 0.5, textTransform: "uppercase" },
  sub: { color: "var(--muted-foreground)", fontSize: 12.5, marginTop: 6 },
  btnRow: { display: "flex", gap: 8, marginTop: 16, flexWrap: "wrap",
            alignItems: "center", paddingTop: 14,
            borderTop: "1px solid var(--border)" },
