         background: "var(--card)", border: "1px solid var(--border)" },
  grid: { display: "grid", gridTemplateColumns: "1fr 1fr", gap: 14, marginTop: 18 },
  label: { fontSize: 11.5, textTransform: "uppercase", letterSpacing: ".06em",
