           borderBottom: "1px solid color-mix(in srgb, var(--border) 45%, transparent)" },
  kvKey: { color: "var(--muted-foreground)", minWidth: 118, flexShrink: 0 },
  kvVal: { wordBreak: "break-word", textAlign: "right", marginLeft: "auto",
           fontVariantNumeric: "tabular-nums" },
  kvEmpty: { color: "var(--muted-foreground)", fontSize: 12.5 },
  /* live-activity feed */
  actBox: { background: "var(--card)", border: "1px solid var(--border)",
            borderRadius: 9, padding: 12 },
  actHead: { display: "flex", alignItems: "center", gap: 8, fontSize: 12.5,
             fontWeight: 600, flexWrap: "wrap" },
  actRow: { display: "flex", alignItems: "baseline", gap: 9, fontSize: 12.5,
            padding: "4px 0", flexWrap: "wrap" },
  actName: { color: "var(--muted-foreground)", minWidth: 150 },
  actMeta: { color: "var(--muted-foreground)", fontSize: 11.5, opacity: 0.85 },
  dotOn: { color: "#3fb950" }, dotOff: { color: "var(--muted-foreground)" },
  dotLive: { color: "#3fb950", fontWeight: 700, width: 12, display: "inline-block" },
  dotIdle: { color: "var(--muted-foreground)", width: 12, display: "inline-block" },
  ckRow: { display: "flex", alignItems: "center", gap: 11, padding: "7px 11px",
           borderRadius: 8, background: "var(--card)", border: "1px solid var(--border)",
           flexWrap: "wrap" },
  ckMeta: { color: "var(--muted-foreground)", fontSize: 11.5,
            fontFamily: "ui-monospace,Menlo,monospace" },
  ckProject: { color: "var(--muted-foreground)", fontSize: 11.5, marginLeft: "auto" },
};

// ---------------------------------------------------------------- the page
function KarpathyLoop(props) {
  const ctx = props.ctx;
  const host2 = ctx.host || host;
  // Route resolution is ASYNC (it consults host2.profileRoutes()), so it lands
  // in state. Until it resolves, route is null and the hooks below stay idle --
  // that is deliberate: passing a half-built route is what threw
  // "reading 'trim'" and blanked every panel.
  const [route, setRoute] = useState(null);
  const [routeErr, setRouteErr] = useState("");
  const [tick, setTick] = useState(0);
  const [busy, setBusy] = useState("");
  const [msg, setMsg] = useState("");
  const [showPicker, setShowPicker] = useState(false);

  useEffect(() => {
    let alive = true;
    currentRoute(host2)
      .then(function (r) {
        if (!alive) return;
        setRoute(r);
        setRouteErr("");
      })
      .catch(function (e) {
        if (!alive) return;
        setRouteErr(String((e && e.message) || e));
      });
    return function () { alive = false; };
  }, [host2, tick]);

  const status = useLoopStatus(host2, route, tick);
  const act0 = useActivity(host2, route, tick);
  const disc = useDiscovery(host2, route, tick);
  const ckpts = useCheckpoints(host2, route, tick);

  const running = !!(status.json && status.json.running);
  const projects = (status.json && status.json.projects) || [];

  // The in-flight worker, and its chain of thought, from the activity feed.
  // NOTE: `.projects` here is a list of NAMES (strings), while `.rows` carries
  // the per-project detail -- the two are not interchangeable.
  const cot = (act0.data && act0.data.cot) || {};
  const actRows = (act0.data && act0.data.rows) || [];
  if (!cot.live) {
    const live = actRows.filter(function (r) { return r.running; })[0];
    if (live) {
      cot.live = { project: live.name, task: live.active_task, elapsed: live.elapsed };
    }
  }

  const act = useCallback(async (label, args, cb) => {
    setBusy(label); setMsg("");
    let out = "";
    try {
      const r = route || (await currentRoute(host2));
      out = await runPy(host2, r, args, 600000);
      const first = out ? out.split("\n").slice(0, 2).join(" · ") : (label + " ok");
      setMsg(first);
      setTick(function (t) { return t + 1; });
    } catch (e) {
      setMsg(label + " failed: " + String(e.message || e).slice(0, 220));
    } finally {
      setBusy("");
    }
    // Some callers need the raw output (e.g. to hand live state to the picker).
    if (typeof cb === "function") { try { cb(out); } catch (e) {} }
    return out;
  }, [host2, route, tick]);

  // The embedded picker posts its config here.
  useEffect(() => {
    const onMsg = function (ev) {
      let payload = ev.data;
      if (typeof payload === "string") {
        try { payload = JSON.parse(payload); } catch (e) { return; }
      }
      if (!payload || !payload.action) return;
      const sel = payload.projects || [];
      const apv = payload.angles_per_visit;
      const impl = payload.implementer;
      const rev = payload.reviewer;

      // Reply channel: the picker re-syncs from live state, because the data
      // baked into selector_data.json is a BUILD-TIME snapshot and goes stale.
      const reply = function (msg) {
        try {
          const w = ev.source || (ev.target && ev.target.defaultView) || window.parent;
          if (w && w.postMessage) w.postMessage(JSON.stringify(msg), "*");
        } catch (e) {}
      };

      if (payload.action === "load") {
        // "what is actually on disk right now?"
        act("Read state", "loopctl.py status --json", function (out) {
          // The output is human text FOLLOWED by a JSON block, so slice from the
          // first "{" to the last "}" rather than parsing the whole thing.
          let live = null;
          try {
            const a = String(out || "").indexOf("{");
            const b = String(out || "").lastIndexOf("}");
            if (a >= 0 && b > a) live = JSON.parse(String(out).slice(a, b + 1));
          } catch (e) {}
          reply({ live: live, action: "live" });
        });
        return;
      }
      if (payload.action === "save") {
        const parts = ["loopctl.py config"];
        parts.push("--projects " + JSON.stringify(sel.join(",")));
        if (apv) parts.push("--angles-per-visit " + apv);
        if (impl) parts.push("--implementer " + JSON.stringify(impl));
        if (rev) parts.push("--reviewer " + JSON.stringify(rev));
        // TWO writes, because the loop reads TWO files:
        //   loop.json    -> the on/off switch, seats, cadence
        //   improve.yaml -> WHICH projects rotate (name/path/board/loops/enabled)
        // Writing only the first is the bug where picks silently vanished.
        // `&&` so a manifest failure surfaces instead of reporting success.
        const sync = 'manifest_sync.py sync --projects ' + JSON.stringify(sel.join(","));
        act("Save rotation", parts.join(" ") + " && " + sync, function (out) {
          // Tell the picker to re-read, so it shows what actually landed.
          reply({ action: "saved", ok: true, out: String(out || "").slice(0, 400) });
        });
      } else if (payload.action === "start") {
        act("Start", "loopctl.py start");
      } else if (payload.action === "pause") {
        act("Pause", 'loopctl.py pause --reason "paused from app"');
      } else if (payload.action === "discover") {
        act("Discovery", "karpathy_cron.py discover");
      }
    };
    window.addEventListener("message", onMsg);
    return function () { window.removeEventListener("message", onMsg); };
  }, [act]);

  // Report the ACTUAL reason instead of a blanket "unavailable" -- an opaque
  // badge is what made this look like a dead widget while it was really a
  // route/permission problem.
  const statusLine = routeErr
    ? "no profile route"
    : (status.error
        ? "status unavailable — " + String(status.error).slice(0, 90)
        : (status.loading ? "loading…" : (running ? "RUNNING" : "PAUSED")));

  return jsxs("div", { style: S.wrap, children: [
    jsxs("div", { style: S.hrow, children: [
      jsx("h2", { style: S.h2, children: "Karpathy Loop" }),
      jsx("span", { style: (routeErr || status.error) ? S.badgeErr
      : (running ? S.badgeOn : S.badgeOff), children: statusLine }),
    ] }),
    jsx("div", { style: S.sub, children:
      "Pick projects, models and review angles; the loop rotates through them and checkpoints every accepted round." }),

    jsxs("div", { style: S.btnRow, children: [
      jsx(Button, { onClick: function () { act("Start", "loopctl.py start"); },
                    disabled: !!busy || running,
                    children: busy === "Start" ? "Starting…" : "Start loop" }),
      jsx(Button, { onClick: function () { act("Pause", 'loopctl.py pause --reason "paused from app"'); },
                    disabled: !!busy || !running,
                    children: busy === "Pause" ? "Pausing…" : "Pause" }),
      jsx(Button, { onClick: function () { act("Discovery", "karpathy_cron.py discover"); },
                    disabled: !!busy,
                    children: busy === "Discovery" ? "Scanning…" : "Run discovery" }),
      jsx(Button, { onClick: function () { setShowPicker(function (v) { return !v; }); },
                    children: showPicker ? "Hide picker" : "Open project picker" }),
      jsx(Button, { onClick: function () { setTick(function (t) { return t + 1; }); },
                    disabled: !!busy, children: "Refresh" }),
    ] }),

    msg ? jsx("div", { style: S.msg, children: msg }) : null,

    /* ── PROJECTS ──────────────────────────────────────────────────────
       First thing on screen: which projects are in the queue, which one is
       mid-round, and how many rounds each has had. This is the "where is it
       running" answer, and it must be readable at a glance -- so it is a
       TABLE, not free-floating text. */
    jsx("div", { style: S.label, children: "Projects in rotation" }),
    (actRows.length
      ? jsx("div", { style: S.tblWrap, children: jsx("table", {
          style: S.tbl, children: [
            jsx("thead", { children: jsx("tr", { children: [
              jsx("th", { style: S.thP, children: "" }),
              jsx("th", { style: S.th, children: "Project" }),
              jsx("th", { style: S.th, children: "State" }),
              jsx("th", { style: S.thR, children: "Rounds" }),
              jsx("th", { style: S.th, children: "Card" }),
              jsx("th", { style: S.thR, children: "Elapsed" }),
            ] }) }),
            jsx("tbody", { children: actRows.map(function (p, i) {
              const active = !!p.running;
              return jsx("tr", { style: active ? S.trLive : S.tr, children: [
                jsx("td", { style: S.tdDot, children: jsx("span", {
                  style: active ? S.dotLive : S.dotIdle,
                  children: active ? "\u25B6" : "\u00b7",
                }) }, i + "d"),
                jsx("td", { style: active ? S.tdNameLive : S.tdName,
                            children: p.name }, i + "n"),
                jsx("td", { style: S.td, children: jsx("span", {
                  style: active ? S.pillRun : (p.never_rotated ? S.pillWait : S.pillIdle),
                  children: active ? "running" : (p.never_rotated ? "waiting" : "idle"),
                }) }, i + "s"),
                jsx("td", { style: S.tdR, children: String(p.rounds || 0) }, i + "r"),
                jsx("td", { style: S.tdMono, children: p.active_task || "\u2014" }, i + "t"),
                jsx("td", { style: S.tdR, children: p.elapsed || "\u2014" }, i + "e"),
              ] }, i);
            }) }),
          ],
        }) })
      : jsx("div", { style: S.empty, children:
          "Nothing yet \u2014 open the picker and tick some repos." })),

    act0.error ? jsx("div", { style: S.err, children: String(act0.error) }) : null,
    jsx("div", { style: { height: 18 } }),

    /* ── CHAIN OF THOUGHT ──────────────────────────────────────────────
       Below the table: the agent's live reasoning and tool steps. This
       replaced a raw JSON dump that told the user nothing. */
    cotCard({ cot: cot, error: null, onRefresh: function () {
      setTick(function (t) { return t + 1; });
    }, busy: !!busy }),

    jsx("div", { style: { height: 18 } }),
    jsxs("div", { style: S.grid, children: [
      jsxs("div", { children: [
        jsx("div", { style: S.label, children: "Loop settings" }),
        settingsRows(status, act0),
      ] }),
      jsxs("div", { children: [
        jsx("div", { style: S.label, children: "Discovery" }),
        discoRows(disc),
      ] }),
    ] }),

    showPicker ? jsxs("div", { style: { marginTop: 18 }, children: [
      jsx("div", { style: S.label, children:
        "Project picker — tick repos, choose models and angles, then Save rotation" }),
      jsx("iframe", {
        src: "file:///" + SEL_HTML.replace(/\\/g, "/"),
        style: S.iframe,
        title: "Karpathy Loop project picker",
      }),
    ] }) : null,

    // --- Checkpoints: the rollback safety net -------------------------
    jsxs("div", { style: { marginTop: 22 }, children: [
      jsxs("div", { style: S.hrow, children: [
        jsx("div", { style: S.label, children:
          "Checkpoints — every round is tagged and pushed; roll any one back" }),
        jsx(Button, { onClick: function () { setTick(function (t) { return t + 1; }); },
                      disabled: !!busy, children: "Refresh checkpoints" }),
      ] }),
      jsx("div", { style: Object.assign({}, S.sub, { margin: "4px 0 10px" }), children:
        "Tags: kp/<project>/r<NN>-start (before a round) and kp/<project>/r<NN> (after). "
        + "Rollback restores that exact state — nothing after it is lost, it stays in git." }),
      (ckpts.loading
        ? jsx("div", { style: S.empty, children: "loading checkpoints…" })
        : (ckpts.error
            ? jsx("pre", { style: Object.assign({}, S.pre, { maxHeight: 120 }), children: ckpts.error })
            : (ckpts.rows.length
                ? jsx("div", { style: { display: "grid", gap: 6 }, children: ckpts.rows.map(function (r, i) {
                    return jsxs("div", { style: S.ckRow, children: [
                      jsx("span", { style: S.mono, children: r.tag }),
                      jsx("span", { style: S.ckMeta, children: (r.created || "").slice(0, 19).replace("T", " ") + "  " + (r.sha || "") }),
                      jsx("span", { style: S.ckProject, children: r.project }),
                      jsx(Button, {
                        onClick: function () {
                          var cmd = "checkpoint.py rollback --repo \"" + r.repo + "\" --project "
                                    + r.project + " \"" + r.tag + "\"";
                          act("Rollback " + r.tag, cmd);
                        },
                        disabled: !!busy,
                        children: busy && busy.indexOf("Rollback") === 0 ? "…" : "Rollback",
                      }),
                    ] }, i);
                  }) })
                : jsx("div", { style: S.empty, children:
                    "No checkpoints yet for the selected projects. Press Start — the loop lays one down before it touches any code." })))),
    ] }),
  ] });
}

// ---------------------------------------------------------------- export
var plugin_default = {
  id: ID,
  name: "Karpathy Loop",
  defaultEnabled: true,
  register(ctx) {
    ctx.register({
      id: "page",
      area: ROUTES_AREA,
      data: { path: "/karpathy" },
      render: function () { return jsx(KarpathyLoop, { ctx: ctx }); },
    });
    ctx.register({
      id: "navigation",
      area: SIDEBAR_NAV_AREA,
      data: { path: "/karpathy", label: "Karpathy Loop", codicon: "sync" },
    });
    ctx.register({
      id: "open",
      area: PALETTE_AREA,
      data: {
        id: "karpathy-loop.open",
        label: "Open Karpathy Loop",
        keywords: ["karpathy", "improve", "loop", "codebase", "rotate", "checkpoint"],
        run: function () { host.navigate("/karpathy"); },
      },
    });
  },
};

export default plugin_default;



===== cot-card.js =====
function cotCard(props) {
  const cot = props.cot || {};
  const steps = cot.steps || [];
  // activity.py does not emit `live`; liveness is implied by having a task and
  // a recently-written log. Treat the log as live for 10 minutes.
  const live = (cot.task && (typeof cot.log_age_s !== "number" || cot.log_age_s < 600))
    ? { project: cot.project, task: cot.task } : null;

  let body;
  if (props.error) {
    body = jsx("div", { style: S.cotErr, children: String(props.error) });
  } else if (!steps.length) {
    body = jsx("div", { style: S.empty, children: live
      ? "waiting for the first step…"
      : "No round in flight. Press Start loop — steps appear here as the agent works." });
  } else {
    body = jsx("div", { style: S.cotScroll,
      children: steps.map(function (s, i) { return cotStep(s, i); }) });
  }

  return jsxs("div", { style: S.cotCard, children: [
    jsxs("div", { style: S.cotHead, children: [
      jsx("span", { style: S.cotTitle, children: "Chain of thought" }),
      jsx("span", { style: S.cotSub, children: live
        ? live.project + " \u00b7 " + live.task
          + (cot.steps_total ? " \u00b7 " + cot.steps_total + " steps" : "")
          + (typeof cot.log_age_s === "number"
              ? " \u00b7 updated " + ago(cot.log_age_s) : "")
        : "nothing in flight" }),
      jsx("span", { style: { marginLeft: "auto" },
        children: jsx(Button, {
          onClick: props.onRefresh, disabled: !!props.busy, children: "Refresh" }) }),
    ] }),
    body,
  ] });
}

/** One step: an italic reasoning card, or a monospace tool line. */
function cotStep(s, i) {
  const isThink = s.kind === "think";
  return jsxs("div", {
    style: isThink ? S.cotThink : S.cotStep,
    key: i,
  }, [
    jsx("span", { style: S.cotIcon,
      children: isThink ? "\u{1F9E0}" : (s.icon || "·") }),
    jsxs("div", { style: S.cotBody, children: [
      jsx("div", { style: isThink ? S.cotThinkText : S.cotStepText,
        children: shorten(isThink ? s.text : tidyPath(s.text),
                          isThink ? 320 : 150) }),
      jsxs("div", { style: S.cotMeta, children: [
        isThink ? "reasoning" : s.kind,
        s.duration ? " · " + s.duration : "",
        s.note ? " · " + shorten(s.note, 80) : "",
      ] }),
    ] }),
  ]);
}
